website = env.ref('website_custom_art_book.website_industry')
MARK = '__EXPORT_FILTER_XMLID__'
for view in env['ir.ui.view'].sudo().search([('website_id', '=', website.id)]):
    arch = view.arch_db or ''
    if MARK not in arch:
        continue
    new_arch = arch
    while MARK in new_arch:
        start = new_arch.index(MARK)
        end = new_arch.index(MARK, start + len(MARK)) + len(MARK)
        xmlid = new_arch[start + len(MARK):end - len(MARK)]
        try:
            resolved = str(env.ref(xmlid).id)
        except ValueError:
            resolved = '0'
        new_arch = new_arch[:start] + resolved + new_arch[end:]
    view.write({'arch_db': new_arch})
